import{z as s,x as l,o as e,c as C,q as r,j as o,D as a,d as t,s as i,S as B,b as A}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"指针认证 PAC","description":"","frontmatter":{"title":"指针认证 PAC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pointer-authentication.md","filePath":"cs/pointer-authentication.md","lastUpdated":1791063341000}'),p={name:"cs/pointer-authentication.md"};function d(P,E,D,c,h,m){const n=l("Mermaid");return e(),C("div",null,[E[2]||(E[2]=r('<h1 id="指针认证-pac" tabindex="-1">指针认证 PAC <a class="header-anchor" href="#指针认证-pac" aria-label="Permalink to &quot;指针认证 PAC&quot;">​</a></h1><div class="epigraph"><p>ARMv8.3 把短 MAC 塞进指针闲置位：改地址而不重签，使用时校验失败。密钥在内核/EL 管理，用户态任意写不再能静默改返回地址或函数指针。</p><footer>—— ARM ARM 对 PAC 的描述；Qualcomm/Apple 的工程叙述；对照 Liljestrand 等对 PAC 的分析</footer></div><p>上一课<a href="/cs/shadow-stack-cet">CET</a>是 x86 侧的硬件 CFI：影子栈钉住控制流转移的边。本课补 ARM 一侧的缺口——<strong>指针签名</strong>（PAC，ARMv8.3 起）：改地址而不重签，使用时校验失败。本课讲两件事：签什么、密钥放在哪；不给伪造 PAC 的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>64 位虚拟地址用不满高位，指针里留有闲置位。PAC 用掉它们：对「地址 + 上下文（如 SP）」用密钥算一个短标签，替换进闲置位；写入时签名，取用前认证。返回地址、函数指针这类一旦被改就能劫持控制流的数据都可签。攻击者若改了地址而不重签，认证时标签对不上，跳转即失败。缺口有二：密钥若泄漏，签名形同虚设；标签位宽有限，有碰撞可能。本课只陈述余量有限，PAC 须与其他缓解配合，不当唯一防线。</p><h3 id="不是加密内存" tabindex="-1">不是加密内存 <a class="header-anchor" href="#不是加密内存" aria-label="Permalink to &quot;不是加密内存&quot;">​</a></h3><p>常见误读是「PAC 加密了内存」：并没有。数据载荷仍是明文，PAC 只管<strong>指针值本身</strong>的完整性——没签过的指针照常用，签过但被改的指针报错。保密性归加密与特权隔离管。</p><p><span class="marginnote">ARM Pointer Authentication。Linux 以 <code>HWCAP_PACA</code> 报告支持。PAC 密钥（APIA、APDB 等）由 EL1/EL2 写入系统寄存器，用户态读不到。本课禁止绕过教程。</span></p><p><span class="marginnote">PAC 的标签本质是 MAC（消息认证码）：拿「指针值 + 上下文」用密钥算一段短校验码。类比快递箱上的一次性封条——箱号（地址）换过，封条就对不上；而想撕掉重贴，需要总部（更高特权级）才有的独家胶水（密钥）。</span></p><p><span class="marginnote">数字实例：常见 ARM64 实现给 PAC 留 7~16 个高位。若标签有 16 位，随机瞎改一个已签指针、恰巧通过校验的概率约 \\(2^{-16}\\)，即六万五千分之一；而且认证失败通常直接抛异常，攻击者连大规模重试的机会都没有。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是与 CET 对照着读：CET 的影子栈管<strong>边</strong>（返回必须落回影子栈记录的地址），PAC 管<strong>指针值</strong>（指针被改则认证失败），保护对象不同，可以叠加。密钥按特权分离：内核与用户态各用各的密钥寄存器，用户态的任意写构造不出内核的签名。下一课：从硬件缓解走到语言迁移。</p>',13)),(e(),o(B,null,{default:a(()=>[i(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%8C%87%E9%92%88%22%5D%20--%3E%20SIGN%5B%22PAC%20%E7%AD%BE%E5%90%8D%22%5D%0A%20%20SIGN%20--%3E%20USE%5B%22%E8%AE%A4%E8%AF%81%E5%90%8E%E4%BD%BF%E7%94%A8%22%5D%0A%20%20TAMPER%5B%22%E6%94%B9%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20FAIL%5B%22%E6%A0%A1%E9%AA%8C%E5%A4%B1%E8%B4%A5%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[t("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"机制要点是认证时机：签名与认证成对出现在函数序言与尾声（或编译器插入的位置），任何未经认证的写都无法把改过的指针送进间接跳转；短 MAC 的安全性在于「改地址必须重签，重签需要密钥」。控制数据的完整性由此有了指令级标签，但这是缓解不是根治——内存破坏仍在，只是被转化为可观测的失败；根治仍是少写 C。下一课内存安全语言迁移：类型与所有权进编译器。",-1)),E[5]||(E[5]=A("p",null,"一次受 PAC 保护的函数调用，返回地址的一生：",-1)),(e(),o(B,null,{default:a(()=>[i(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22%E8%B0%83%E7%94%A8%EF%BC%9A%E8%BF%94%E5%9B%9E%E5%9C%B0%E5%9D%80%E8%BF%9B%E5%85%A5%E9%93%BE%E6%8E%A5%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%20--%3E%20SIGN%5B%22%E5%BA%8F%E8%A8%80%EF%BC%9A%E7%94%A8%E5%AF%86%E9%92%A5%E7%BB%99%E8%BF%94%E5%9B%9E%E5%9C%B0%E5%9D%80%E7%AD%BE%E5%90%8D%22%5D%0A%20%20SIGN%20--%3E%20STORE%5B%22%E5%B8%A6%E6%A0%87%E7%AD%BE%E7%9A%84%E6%8C%87%E9%92%88%E5%AD%98%E5%85%A5%E6%A0%88%E5%B8%A7%22%5D%0A%20%20STORE%20--%3E%20ATTACK%5B%22%E6%94%BB%E5%87%BB%E8%80%85%E6%A0%88%E6%BA%A2%E5%87%BA%E6%94%B9%E5%86%99%E8%BF%99%E4%B8%AA%E6%A7%BD%E4%BD%8D%22%5D%0A%20%20ATTACK%20--%3E%20LOAD%5B%22%E5%B0%BE%E5%A3%B0%EF%BC%9A%E4%BB%8E%E6%A0%88%E8%AF%BB%E5%9B%9E%E6%8C%87%E9%92%88%22%5D%0A%20%20LOAD%20--%3E%20AUTH%5B%22%E7%94%A8%E5%90%8C%E4%B8%80%E5%AF%86%E9%92%A5%E9%87%8D%E7%AE%97%E6%A0%87%E7%AD%BE%E6%AF%94%E5%AF%B9%22%5D%0A%20%20AUTH%20--%3E%7C%22%E5%AF%B9%E4%B8%8A%22%7C%20RET%5B%22%E6%8C%89%E5%8E%9F%E8%BF%94%E5%9B%9E%E5%9C%B0%E5%9D%80%E8%BF%94%E5%9B%9E%22%5D%0A%20%20AUTH%20--%3E%7C%22%E5%AF%B9%E4%B8%8D%E4%B8%8A%22%7C%20TRAP%5B%22%E8%AE%A4%E8%AF%81%E5%A4%B1%E8%B4%A5%EF%BC%8C%E8%B7%B3%E8%BD%AC%E8%A2%AB%E6%8B%A6%E4%B8%8B%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">常见误区：以为开了 PAC 内存就被加密、指针就「不可写」。数据照旧明文可写，没签过名的指针（比如堆上的普通数据指针）完全不受保护——PAC 只拦「被签名的控制数据被改」这一条路，所以说它是缓解，不是根治。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不分析 PAC 碰撞的构造，也不给绕过案例。内存安全语言下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CET 钉控制流的边；PAC 钉指针值本身。</li><li>短 MAC 藏在指针闲置位；密钥由更高特权持有。</li><li>位宽有限、密钥可泄漏，须与其他缓解叠加。</li><li>下一课内存安全语言。</li><li>出处：ARM ARM；Liljestrand et al.；对照 Intel CET。</li></ul>',5))])}const F=s(p,[["render",d]]);export{T as __pageData,F as default};
